// TH18 v1.00a Stage 3 mid-stage wave 2 (MainSub01).
// Source: st03.ecl.txt:1087-1119; closure GirlB01 / GirlB01_at at 407-482.
// Four groups of six GirlB01: left (-224,96), mirrored right (224,96),
// 40 frames between spawns (24 spawns, last at source frame 920, returns 960).

const TIME_LIMIT: int = 1500;     // 120 shell buffer + 960 spawn schedule + volley/tail estimate
const TH18_RING_BALL2: int = 464; // TH18 etSprite type 7 (RingBall2), color 6, base radius 4

// Source st03.ecl.txt:447: etEx type 0x200000, a=120, r=1.0, s=-1000000.
// Direction is the bullet's launch angle; scalar speed falls linearly S -> 1.0
// over 120 updates. s=-1000000 is below the -999990 sentinel, so it keeps the
// current angle (ex-effects.md VELTIME table).
xformdef VELTIME_TO_1 {
    step_speed(1fx, 120 + 65536 * EASE_LINEAR);
}

// Source st03.ecl.txt:427-482 (GirlB01_at). One async task per enemy.
async sub girl_b01_at() {
    wait(rand(60));                  // 430: wait($RAND % 60)

    var rank: int = global(GVAR_RANK);
    // 436-444: launch speed by rank; 452: burst shot count;
    // 456-464 / 468-475: per-shot and per-burst waits by rank.
    var speed: fx = 3fx;             // E
    var shots: int = 1;
    var inner: int = 10;
    var outer_base: int = 80;
    if rank == 1 { speed = 4fx; shots = 3; outer_base = 40; }
    if rank == 2 { speed = 4.5fx; shots = 6; inner = 5; outer_base = 10; }
    if rank == 3 { speed = 5fx; shots = 10; inner = 3; outer_base = 10; }

    sh_reset(0);
    sh_sprite(0, TH18_RING_BALL2, 6); // 433: etSprite(0, 7, 6)
    sh_aim(0, 1);                     // 432: etAim(0, 0), resolved at each fire
    sh_ring(0, 0);
    sh_count(0, 1, 1);                // 434: etCount(0, 1, 1)
    sh_angle(0, 0deg, 0deg);          // 435: delta unused for a single way
    sh_speed(0, speed, 0fx);          // 445: etSpeed(0, [-1], 1.0), M=1 takes S
    sh_xform(0, VELTIME_TO_1);        // 447: etEx(0,0,0x200000,120,...,1.0,-1000000)
    // 446 etEx type 2/ANIM a=1: position -= 4*velocity at birth. Keep that
    // displacement by spawning each bullet 4 frames back along its own angle.
    sh_dist(0, 0fx - 4fx * speed);

    var burst: int = 3;               // 449: $A = 3
    while burst > 0 {
        var n: int = shots;           // 452: diffI($B, 1, 3, 6, 10)
        while n > 0 {
            sh_fire(0);               // 455: etOn(0)
            wait(inner);              // 456-465: wait([-1])
            n = n - 1;
        }
        wait(outer_base + rand(20));  // 468-477: rank wait + ($RAND % 20)
        burst = burst - 1;
    }
}

// Source st03.ecl.txt:407-425 (GirlB01 body).
async sub girl_b01(start_a: angle, turn_a: angle) {
    set_hurtbox(16fx);                      // 413: setHurtbox(32) -> radius 16
    set_hitbox(12fx);                       // 414: setHitbox(24)  -> radius 12
    move_vel(0, start_a, 4fx, EASE_LINEAR); // 415: moveVel(-0.17889625, 4.0)
    spawn girl_b01_at();                    // 416: @GirlB01_at() async
    wait(60);                               // 417
    move_vel(60, turn_a, 1fx, EASE_QUAD_IN); // 418: moveVelTime(60, mode1, 2.9452431, 1.0)
    loop { wait(1000); }                    // 420-423: never returns; off-screen recycle
}

// Source st03.ecl.txt:1089-1118: $A..$D = 6, 24 spawns, 40-frame interval.
// enmCreateM is the mirrored create: child mirror flag starts set, so its
// movement angles are reflected as 180deg - angle (enemy-state.md section 2-3).
async sub wave_pattern() {
    wait(120);                              // shell pre-attack buffer
    for i in 0..24 {
        var mirror: int = (i / 6) % 2;
        var px: fx = -224fx;
        var a0: angle = 63670 as angle;     // -10.25deg (source -0.17889625 rad)
        var a1: angle = 30720 as angle;     // 168.75deg (source 2.9452431 rad)
        if mirror != 0 {
            px = 224fx;
            a0 = 32768 as angle - a0;
            a1 = 32768 as angle - a1;
        }
        _ = spawn_enemy(px, 96fx, 500, 0, 0, 0, girl_b01(a0, a1));
        wait(40);                           // 1094/1101/1108/1115
    }
    loop { wait(60); }                      // phase timer owns the tail
}

// Invincible practice shell: separate control enemy at (0,0), body collision off.
async sub wave_control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    set_hitbox(0fx);
    set_hurtbox(0fx);
    phase_begin(0, wave_pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, wave_control);
    loop { wait(600); }
}
